231	/* 串口读取线程：poll → read → 状态机 → 提取目标状态/距离
232	 * 2026-08-23 审查修复（FAIL1）：O_NONBLOCK 直 read 无数据时忙转烧 CPU，
233	 * 改 poll(POLLIN, 200ms) 带超时等待——无数据时线程休眠，不空转。 */
234	static void *ld2410b_reader(void *arg)
235	{
236	  int      fd = (int)(intptr_t)arg;
237	  uint8_t  buf[64];
238	  uint8_t  frame[FRAME_MAX_LEN];
239	  int      fpos = 0;
240	  int      flen = 0;
241	  int      st   = ST_WAIT_HDR;
242	  int      last_report_ts = 0;
243	  struct pollfd pfd;
244	
245	  pfd.fd     = fd;
246	  pfd.events = POLLIN;
247	
248	  while (g_ld2410b_run)
249	    {
250	      int pr = poll(&pfd, 1, 200);
251	      if (pr <= 0)
252	        continue;                    /* 超时/无数据：正常休眠重试 */
253	
254	      ssize_t n = read(fd, buf, sizeof(buf));
255	      if (n > 0)
256	        g_ld2410b_rx_bytes += n;       /* 调试：累计收到字节数 */
257	
258	      /* 2026-08-26 调试：每 5s 无条件打印一次收字节/有效帧数——
259	       *  零信号时也打印 rx=0B，可区分「线程活着但无信号」vs「有信号」；
260	       *  回环测试（短接 TX/RX 后 echo /dev/uart0）时 rx 应增长 */
261	      if (lv_tick_get() - last_report_ts > 5000)
262	        {
263	          last_report_ts = lv_tick_get();
264	          LV_LOG_USER("[ld2410b] rx=%uB frames=%u", g_ld2410b_rx_bytes,
265	                      g_ld2410b_frame_cnt);
266	        }
267	
268	      if (n <= 0)
269	        continue;                    /* 无数据可读（非阻塞，直接重试） */
270	
271	      for (ssize_t i = 0; i < n; i++)
272	        {
273	          uint8_t b = buf[i];
274	
275	          switch (st)
276	            {
277	            case ST_WAIT_HDR:
278	              if (b == FRAME_HDR0) st = ST_HDR1;
279	              break;
280	            case ST_HDR1:
281	              st = (b == FRAME_HDR1) ? ST_HDR2 : ST_WAIT_HDR;
282	              break;
283	            case ST_HDR2:
284	              st = (b == FRAME_HDR2) ? ST_HDR3 : ST_WAIT_HDR;
285	              break;
286	            case ST_HDR3:
287	              st = (b == FRAME_HDR3) ? ST_LEN_LO : ST_WAIT_HDR;
288	              break;
289	            case ST_LEN_LO:
290	              flen = b;
291	              st   = ST_LEN_HI;
292	              break;
293	            case ST_LEN_HI:
294	              flen |= (b << 8);
295	              if (flen < DATA_LEN_BASIC || flen > FRAME_MAX_LEN)
296	                {
297	                  st = ST_WAIT_HDR;  /* 长度非法，重新找头 */
298	                }
299	              else
300	                {
301	                  fpos = 0;
302	                  st   = ST_DATA;
303	                }
304	              break;
305	            case ST_DATA:
306	              frame[fpos++] = b;
307	              if (fpos >= flen)
308	                st = ST_TAIL0;
309	              break;
310	            case ST_TAIL0:
311	              st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_WAIT_HDR;
312	              break;
313	            case ST_TAIL1:
314	              st = (b == FRAME_TAIL1) ? ST_TAIL2 : ST_WAIT_HDR;
315	              break;
316	            case ST_TAIL2:
317	              st = (b == FRAME_TAIL2) ? ST_TAIL3 : ST_WAIT_HDR;
318	              break;
319	            case ST_TAIL3:
320	              if (b == FRAME_TAIL3)
321	                {
322	                  ld2410b_parse_frame(frame, flen);   /* 一帧收齐 */
323	                }
324	              st = ST_WAIT_HDR;
325	              break;
326	            default:
327	              st = ST_WAIT_HDR;
328	              break;
329	            }
330	        }
331	    }
332	
333	  close(fd);
334	  return NULL;
335	}
