352	      LV_LOG_ERROR("[ld2410b] open %s failed: %d", LD2410B_DEV, errno);
353	      return -1;
354	    }
355	
356	  /* 115200 8N1，raw 模式 */
357	  memset(&tio, 0, sizeof(tio));
358	  if (tcgetattr(fd, &tio) < 0)
359	    {
360	      close(fd);
361	      return -1;
362	    }
363	  cfmakeraw(&tio);
364	  cfsetispeed(&tio, LD2410B_BAUD);
365	  cfsetospeed(&tio, LD2410B_BAUD);
366	  tio.c_cflag |= (CLOCAL | CREAD);
367	  if (tcsetattr(fd, TCSANOW, &tio) < 0)
368	    {
369	      close(fd);
370	      return -1;
371	    }
372	
373	  /* 2026-08-26：初始化下发模块配置（最大距离门 + 无人延时，命令 0x0060）。
374	   * best-effort：模块未接/波特率仍为 256000 时静默失败，不影响主流程。 */
375	  ld2410b_apply_config(fd);
376	
377	  g_ld2410b_run = true;
378	  if (pthread_create(&g_ld2410b_thread, NULL, ld2410b_reader,
379	                     (void *)(intptr_t)fd) != 0)
380	    {
381	      close(fd);
382	      g_ld2410b_run = false;
383	      return -1;
384	    }
385	
386	  g_ld2410b_ready = true;
387	  LV_LOG_USER("[ld2410b] init ok (%s @115200)", LD2410B_DEV);
388	  return 0;
389	}
