/*
 * ui_uart_dbg.c — UART 调试工具子页（嵌套于 Settings）【2026-08-27 新增】
 *
 * 需求：Settings → UART 调试工具，接收其他设备经串口发来的 debug log。
 * 布局：左侧工具栏（波特率 5 档循环 / ASCII·HEX 显示切换 / 暂停 / 清屏
 *       + 串口状态卡）+ 右侧深色终端滚动窗口（自动滚底）。
 * 数据流：dm_uart_dbg 后台线程收串口 → 8KB 环形缓冲 → 本页 lv_timer
 *       200ms 消费 → 文本缓冲 → label 显示（超限丢最旧）。
 * 生命周期：进入子页 create 时 dm_uart_dbg_open()；close_subpage 调
 *       ui_uart_dbg_close_cleanup() 停 timer + 关串口（并恢复 LD2410B）。
 *
 * 共享宏/工具（DM/COL/FONT、make_clean_cont、subpage_big_title、
 * settings_row_value 等）来自 deskmate_ui.h。
 */

#include <stdio.h>
#include <string.h>
#include <lvgl/lvgl.h>

#include "deskmate_ui.h"
#include "dm_uart_dbg.h"

/* ================================================================
 * UART 调试工具子页状态
 * ================================================================ */

/* 终端文本缓冲（渲染后文本；超限从头部丢弃，防无限增长） */
#define UART_DBG_TEXT_MAX   6000
static char        g_uart_dbg_text[UART_DBG_TEXT_MAX];
static int         g_uart_dbg_text_len;

static lv_obj_t   *uart_dbg_term;       /* 右侧终端滚动容器 */
static lv_obj_t   *uart_dbg_tl;         /* 终端 label */
static lv_obj_t   *uart_dbg_baud_val;   /* 波特率行 value */
static lv_obj_t   *uart_dbg_mode_val;   /* 显示模式行 value */
static lv_obj_t   *uart_dbg_pause_val;  /* 暂停行 value */
static lv_obj_t   *uart_dbg_status_lbl; /* 串口状态卡文字 */
static lv_timer_t *uart_dbg_timer;      /* 200ms 消费环形缓冲 */

static int         uart_dbg_baud_idx;   /* 当前波特率档位索引 */
static bool        uart_dbg_hex;        /* true=HEX 显示 */
static bool        uart_dbg_paused;     /* true=暂停刷新 */

/* ================================================================
 * 文本缓冲工具
 * ================================================================ */

/* 追加渲染后文本；超限从头部丢弃旧内容 */
static void uart_dbg_append(const char *s)
{
    int sl = (int)strlen(s);
    if (sl <= 0)
        return;
    if (g_uart_dbg_text_len + sl >= UART_DBG_TEXT_MAX) {
        int keep = UART_DBG_TEXT_MAX - sl - 1;
        if (keep <= 0) {
            /* 单次追加就超过上限：只保留尾部 */
            strncpy(g_uart_dbg_text, s + (sl - keep + 1), keep);
            g_uart_dbg_text[keep] = '\0';
            g_uart_dbg_text_len   = keep;
            return;
        }
        memmove(g_uart_dbg_text, g_uart_dbg_text + (g_uart_dbg_text_len - keep),
                keep);
        g_uart_dbg_text_len = keep;
        g_uart_dbg_text[keep] = '\0';
    }
    memcpy(g_uart_dbg_text + g_uart_dbg_text_len, s, sl);
    g_uart_dbg_text_len += sl;
    g_uart_dbg_text[g_uart_dbg_text_len] = '\0';
}

/* 把一段原始字节按当前模式渲染为文本并追加。
 * ASCII：可打印直出，\r\n 归一为 \n；非打印转 '.'。
 * HEX：每字节 "%02X "。 */
static void uart_dbg_feed(const uint8_t *buf, int n)
{
    char tmp[256];
    int  ti = 0;

    if (uart_dbg_hex) {
        for (int i = 0; i < n; i++) {
            if (ti >= (int)sizeof(tmp) - 4) {
                tmp[ti] = '\0';
                uart_dbg_append(tmp);
                ti = 0;
            }
            ti += snprintf(tmp + ti, sizeof(tmp) - ti, "%02X ", buf[i]);
        }
    } else {
        for (int i = 0; i < n; i++) {
            uint8_t b = buf[i];
            if (b == '\r')
                continue;               /* 归一化：丢弃 \r，\n 换行 */
            if (ti >= (int)sizeof(tmp) - 2) {
                tmp[ti] = '\0';
                uart_dbg_append(tmp);
                ti = 0;
            }
            if (b == '\n')
                tmp[ti++] = '\n';
            else if (b >= 0x20 && b < 0x7F)
                tmp[ti++] = (char)b;
            else
                tmp[ti++] = '.';
        }
    }
    if (ti > 0) {
        tmp[ti] = '\0';
        uart_dbg_append(tmp);
    }
}

/* 终端滚动到底部 */
static void uart_dbg_scroll_bottom(void)
{
    if (uart_dbg_term && uart_dbg_tl)
        lv_obj_scroll_to_y(uart_dbg_term, lv_obj_get_height(uart_dbg_tl),
                           LV_ANIM_OFF);
}

/* ================================================================
 * 左侧工具栏回调
 * ================================================================ */

/* 波特率：点击循环到下一档（9600 → … → 115200 → 9600） */
static void uart_dbg_baud_cb(lv_event_t *e)
{
    (void)e;
    uart_dbg_baud_idx = (uart_dbg_baud_idx + 1) % DM_UART_DBG_BAUD_CNT;
    speed_t b = dm_uart_dbg_bauds[uart_dbg_baud_idx].baud;
    dm_uart_dbg_set_baud(b);
    if (uart_dbg_baud_val)
        lv_label_set_text(uart_dbg_baud_val,
                          dm_uart_dbg_bauds[uart_dbg_baud_idx].label);
    LV_LOG_USER("[uart_dbg] baud -> %s",
                dm_uart_dbg_bauds[uart_dbg_baud_idx].label);
}

/* 显示模式：ASCII ↔ HEX 切换（切换即清屏，避免新旧格式混排歧义） */
static void uart_dbg_mode_cb(lv_event_t *e)
{
    (void)e;
    uart_dbg_hex = !uart_dbg_hex;
    dm_uart_dbg_clear();
    g_uart_dbg_text_len = 0;
    g_uart_dbg_text[0]  = '\0';
    if (uart_dbg_tl)
        lv_label_set_text(uart_dbg_tl, "");
    if (uart_dbg_mode_val)
        lv_label_set_text(uart_dbg_mode_val, uart_dbg_hex ? "HEX" : "ASCII");
}

/* 暂停/继续：暂停时 timer 不消费（环形缓冲继续收，恢复后补显示） */
static void uart_dbg_pause_cb(lv_event_t *e)
{
    (void)e;
    uart_dbg_paused = !uart_dbg_paused;
    if (uart_dbg_pause_val)
        lv_label_set_text(uart_dbg_pause_val,
                          uart_dbg_paused ? "继续" : "暂停");
}

/* 清屏：清环形缓冲 + 清文本 */
static void uart_dbg_clear_cb(lv_event_t *e)
{
    (void)e;
    dm_uart_dbg_clear();
    g_uart_dbg_text_len = 0;
    g_uart_dbg_text[0]  = '\0';
    if (uart_dbg_tl)
        lv_label_set_text(uart_dbg_tl, "");
}

/* ================================================================
 * 刷新 timer：消费环形缓冲 → 渲染 → 滚动到底
 * ================================================================ */

static void uart_dbg_timer_cb(lv_timer_t *t)
{
    (void)t;
    uint8_t chunk[256];
    int     n;

    if (uart_dbg_paused)
        return;

    while ((n = dm_uart_dbg_read(chunk, sizeof(chunk))) > 0)
        uart_dbg_feed(chunk, n);

    if (g_uart_dbg_text_len > 0 && uart_dbg_tl)
        lv_label_set_text(uart_dbg_tl, g_uart_dbg_text);

    if (uart_dbg_status_lbl)
        lv_label_set_text_fmt(uart_dbg_status_lbl,
                              "%s  %u 字节",
                              dm_uart_dbg_is_open() ? "已连接" : "未连接",
                              (unsigned)dm_uart_dbg_total());

    uart_dbg_scroll_bottom();
}

/* ================================================================
 * 子页构建（show_subpage("UART") → deskmate_ui.c dispatch）
 * ================================================================ */

void ui_uart_dbg_create(lv_obj_t *parent)
{
    lv_obj_t *big_title = subpage_big_title(parent, "UART 调试");
    lv_obj_set_style_pad_bottom(big_title, 12, 0);

    /* 左右两栏：左工具栏（固定宽）+ 右终端（flex_grow） */
    lv_obj_t *row = make_clean_cont(parent);
    lv_obj_set_size(row, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_START);
    lv_obj_set_style_pad_column(row, DM(20), 0);

    /* ── 左侧工具栏：状态卡 + 4 个功能行 ── */
    lv_obj_t *left = lv_obj_create(row);
    lv_obj_set_size(left, DM(190), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(left, LV_OPA_0, 0);
    lv_obj_set_style_border_width(left, 0, 0);
    lv_obj_set_flex_flow(left, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(left, 0, 0);
    lv_obj_set_style_pad_row(left, DM(16), 0);

    /* 串口状态卡 */
    lv_obj_t *st_card = lv_obj_create(left);
    lv_obj_set_size(st_card, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_add_style(st_card, &style_card, 0);
    lv_obj_set_style_radius(st_card, RAD_CARD, 0);
    lv_obj_set_style_pad_all(st_card, DM(16), 0);
    lv_obj_set_flex_flow(st_card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(st_card, DM(6), 0);

    lv_obj_t *st_t = lv_label_create(st_card);
    lv_label_set_text(st_t, "串口");
    lv_obj_set_style_text_font(st_t, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(st_t, lv_color_hex(COL_SEC), 0);

    uart_dbg_status_lbl = lv_label_create(st_card);
    lv_label_set_text(uart_dbg_status_lbl, "未连接");
    lv_obj_set_style_text_font(uart_dbg_status_lbl, FONT_BODY, 0);
    lv_obj_set_style_text_color(uart_dbg_status_lbl,
                                lv_color_hex(COL_BLUE), 0);
    lv_label_set_long_mode(uart_dbg_status_lbl, LV_LABEL_LONG_WRAP);

    /* 波特率行（点击循环切换） */
    uart_dbg_baud_idx = 0;
    for (int i = 0; i < DM_UART_DBG_BAUD_CNT; i++) {
        if (dm_uart_dbg_bauds[i].baud == DM_UART_DBG_BAUD_DEFAULT) {
            uart_dbg_baud_idx = i;
            break;
        }
    }
    lv_obj_t *bd_row = settings_row_value(left, LV_SYMBOL_SETTINGS, COL_BLUE,
                                          "波特率",
                                          dm_uart_dbg_bauds[uart_dbg_baud_idx].label,
                                          true);
    uart_dbg_baud_val = lv_obj_get_child(bd_row, -1);
    lv_obj_add_event_cb(bd_row, uart_dbg_baud_cb, LV_EVENT_CLICKED, NULL);

    /* 显示模式行（ASCII/HEX 切换） */
    lv_obj_t *md_row = settings_row_value(left, LV_SYMBOL_EDIT, COL_PURPLE,
                                          "显示", "ASCII", true);
    uart_dbg_mode_val = lv_obj_get_child(md_row, -1);
    lv_obj_add_event_cb(md_row, uart_dbg_mode_cb, LV_EVENT_CLICKED, NULL);

    /* 暂停/继续行 */
    lv_obj_t *pa_row = settings_row_value(left, LV_SYMBOL_PAUSE, COL_ORANGE,
                                          "暂停", "暂停", true);
    uart_dbg_pause_val = lv_obj_get_child(pa_row, -1);
    lv_obj_add_event_cb(pa_row, uart_dbg_pause_cb, LV_EVENT_CLICKED, NULL);

    /* 清屏行 */
    lv_obj_t *cl_row = settings_row_value(left, LV_SYMBOL_TRASH, COL_RED,
                                          "清屏", "清空", true);
    lv_obj_add_event_cb(cl_row, uart_dbg_clear_cb, LV_EVENT_CLICKED, NULL);

    /* ── 右侧：深色终端滚动窗口 ── */
    uart_dbg_term = lv_obj_create(row);
    lv_obj_set_flex_grow(uart_dbg_term, 1);
    lv_obj_set_height(uart_dbg_term, DM(560));
    lv_obj_set_style_bg_color(uart_dbg_term, lv_color_hex(0x101014), 0);
    lv_obj_set_style_bg_opa(uart_dbg_term, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(uart_dbg_term, RAD_CARD, 0);
    lv_obj_set_style_border_width(uart_dbg_term, 0, 0);
    lv_obj_set_style_pad_all(uart_dbg_term, DM(14), 0);
    lv_obj_set_scrollbar_mode(uart_dbg_term, LV_SCROLLBAR_MODE_AUTO);
    lv_obj_add_flag(uart_dbg_term, LV_OBJ_FLAG_SCROLLABLE);

    uart_dbg_tl = lv_label_create(uart_dbg_term);
    lv_label_set_long_mode(uart_dbg_tl, LV_LABEL_LONG_WRAP);
    lv_label_set_text(uart_dbg_tl, "");
    lv_obj_set_width(uart_dbg_tl, lv_pct(100));
    lv_obj_set_style_text_font(uart_dbg_tl, FONT_BODY, 0);
    lv_obj_set_style_text_color(uart_dbg_tl, lv_color_hex(0xE8E8EA), 0);

    /* 打开串口（默认 /dev/uart0 @115200；LD2410B 让位） */
    dm_uart_dbg_open(DM_UART_DBG_BAUD_DEFAULT);

    /* 200ms 刷新 timer */
    uart_dbg_timer = lv_timer_create(uart_dbg_timer_cb, 200, NULL);
    uart_dbg_timer_cb(NULL);           /* 立即刷一次状态卡 */
}

/* close_subpage 清理（deskmate_ui.c 调用）：停 timer + 关串口 + 置空 */
void ui_uart_dbg_close_cleanup(void)
{
    if (uart_dbg_timer) {
        lv_timer_del(uart_dbg_timer);
        uart_dbg_timer = NULL;
    }
    dm_uart_dbg_close();               /* 内部恢复 LD2410B（若曾让位） */

    uart_dbg_term      = NULL;
    uart_dbg_tl        = NULL;
    uart_dbg_baud_val  = NULL;
    uart_dbg_mode_val  = NULL;
    uart_dbg_pause_val = NULL;
    uart_dbg_status_lbl = NULL;
    g_uart_dbg_text_len = 0;
    g_uart_dbg_text[0]  = '\0';
}

