111	int dm_uart_dbg_open(speed_t baud)
112	{
113	  struct termios tio;
114	  int fd;
115	
116	  if (g_dbg_open)
117	    return 0;                        /* 已打开 */
118	
119	  /* 与 LD2410B 互斥：它占用 /dev/uart0 时暂停让位（deinit 幂等，
120	   * 返回 1=确实在运行；记录以便 close 时恢复） */
121	  g_dbg_ld2410b_was = (dm_ld2410b_deinit() == 1);
122	
123	  fd = open(DM_UART_DBG_DEV, O_RDWR | O_NONBLOCK);
124	  if (fd < 0)
125	    {
126	      LV_LOG_ERROR("[uart_dbg] open %s failed: %d", DM_UART_DBG_DEV, errno);
127	      return -1;
128	    }
129	
130	  /* raw 模式 + 波特率 8N1 */
131	  memset(&tio, 0, sizeof(tio));
132	  if (tcgetattr(fd, &tio) < 0)
133	    {
134	      close(fd);
135	      return -1;
136	    }
137	  cfmakeraw(&tio);
138	  cfsetispeed(&tio, baud);
139	  cfsetospeed(&tio, baud);
140	  tio.c_cflag |= (CLOCAL | CREAD);
141	  if (tcsetattr(fd, TCSANOW, &tio) < 0)
142	    {
143	      close(fd);
144	      return -1;
145	    }
146	
147	  g_dbg_fd = fd;
148	  g_dbg_ring_head = 0;
149	  g_dbg_ring_count = 0;
150	  g_dbg_total = 0;
151	  g_dbg_run = true;
152	  if (pthread_create(&g_dbg_thread, NULL, uart_dbg_reader,
153	                     (void *)(intptr_t)fd) != 0)
154	    {
155	      close(fd);
156	      g_dbg_fd = -1;
157	      g_dbg_run = false;
158	      return -1;
159	    }
160	
161	  g_dbg_open = true;
162	  LV_LOG_USER("[uart_dbg] open %s ok", DM_UART_DBG_DEV);
163	  return 0;
164	}
