void ui_uart_dbg_create(lv_obj_t *parent)
{
    /* 2026-08-27 修复：缺 flex column 导致标题/内容全部叠左上角
     * （对照 ui_wifi.c 修复记录）——必须先设 parent 为列布局 */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(parent, DM(6), 0);

    lv_obj_t *big_title = subpage_big_title(parent, "UART 调试");
    lv_obj_set_style_pad_bottom(big_title, 12, 0);

    /* 左右两栏：左工具栏（固定窄宽）+ 右终端（flex_grow 撑满剩余）。
     * row 高度 = lv_pct(100) 占满可用区（flex column 下剩余高度），
     * 终端高度 lv_pct(100) 跟随 row——不再用 DM(560) 固定高度（1344px
     * 超屏导致黑框无底）。 */
    lv_obj_t *row = make_clean_cont(parent);
    lv_obj_set_size(row, lv_pct(100), lv_pct(100));
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_STRETCH,
                          LV_FLEX_ALIGN_STRETCH);
    lv_obj_set_style_pad_column(row, DM(20), 0);

    /* ── 左侧工具栏：状态卡 + 4 个功能行（收窄到 DM(150)）── */
    lv_obj_t *left = lv_obj_create(row);
    lv_obj_set_size(left, DM(150), LV_SIZE_CONTENT);
    lv_obj_set_style_bg_opa(left, LV_OPA_0, 0);
    lv_obj_set_style_border_width(left, 0, 0);
    lv_obj_set_flex_flow(left, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_all(left, 0, 0);
    lv_obj_set_style_pad_row(left, DM(10), 0);

    /* 串口状态卡（紧凑：标题 + 状态/字节数一行） */
    lv_obj_t *st_card = lv_obj_create(left);
    lv_obj_set_size(st_card, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_add_style(st_card, &style_card, 0);
    lv_obj_set_style_radius(st_card, RAD_CARD, 0);
    lv_obj_set_style_pad_all(st_card, DM(10), 0);
    lv_obj_set_flex_flow(st_card, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(st_card, DM(4), 0);

    lv_obj_t *st_t = lv_label_create(st_card);
    lv_label_set_text(st_t, "串口");
    lv_obj_set_style_text_font(st_t, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(st_t, lv_color_hex(COL_SEC), 0);

    uart_dbg_status_lbl = lv_label_create(st_card);
    lv_label_set_text(uart_dbg_status_lbl, "未连接");
    lv_obj_set_style_text_font(uart_dbg_status_lbl, FONT_BODY, 0);
    lv_obj_set_style_text_color(uart_dbg_status_lbl,
                                lv_color_hex(COL_BLUE), 0);
    lv_label_set_long_mode(uart_dbg_status_lbl, LV_LABEL_LONG_WRAP);

    /* 波特率行（点击循环切换） */
    uart_dbg_baud_idx = 0;
    for (int i = 0; i < DM_UART_DBG_BAUD_CNT; i++) {
        if (dm_uart_dbg_bauds[i].baud == DM_UART_DBG_BAUD_DEFAULT) {
            uart_dbg_baud_idx = i;
            break;
        }
    }
    lv_obj_t *bd_row = uart_dbg_tool_row(left, LV_SYMBOL_SETTINGS, COL_BLUE,
                                         "波特率",
                                         dm_uart_dbg_bauds[uart_dbg_baud_idx].label,
                                         uart_dbg_baud_cb);
    uart_dbg_baud_val = lv_obj_get_user_data(bd_row);

    /* 显示模式行（ASCII/HEX 切换） */
    lv_obj_t *md_row = uart_dbg_tool_row(left, LV_SYMBOL_EDIT, COL_PURPLE,
                                         "显示", "ASCII", uart_dbg_mode_cb);
    uart_dbg_mode_val = lv_obj_get_user_data(md_row);

    /* 暂停/继续行 */
    lv_obj_t *pa_row = uart_dbg_tool_row(left, LV_SYMBOL_PAUSE, COL_ORANGE,
                                         "暂停", "暂停", uart_dbg_pause_cb);
    uart_dbg_pause_val = lv_obj_get_user_data(pa_row);

    /* 清屏行 */
    lv_obj_t *cl_row = uart_dbg_tool_row(left, LV_SYMBOL_TRASH, COL_RED,
                                         "清屏", "清空", uart_dbg_clear_cb);
    (void)cl_row;

    /* ── 右侧：浅色终端滚动窗口（Liquid Glass：白底/白边/轻阴影）── */
    uart_dbg_term = lv_obj_create(row);
    lv_obj_set_flex_grow(uart_dbg_term, 1);
    lv_obj_set_height(uart_dbg_term, lv_pct(100));
    lv_obj_set_style_bg_color(uart_dbg_term, lv_color_hex(COL_CARD), 0);
    lv_obj_set_style_bg_opa(uart_dbg_term, LV_OPA_70, 0);
    lv_obj_set_style_radius(uart_dbg_term, RAD_CARD, 0);
    lv_obj_set_style_border_width(uart_dbg_term, 1, 0);
    lv_obj_set_style_border_color(uart_dbg_term, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_border_opa(uart_dbg_term, LV_OPA_50, 0);
    lv_obj_set_style_shadow_width(uart_dbg_term, 6, 0);
    lv_obj_set_style_shadow_opa(uart_dbg_term, LV_OPA_10, 0);
    lv_obj_set_style_pad_all(uart_dbg_term, DM(14), 0);
    lv_obj_set_scrollbar_mode(uart_dbg_term, LV_SCROLLBAR_MODE_AUTO);
    lv_obj_add_flag(uart_dbg_term, LV_OBJ_FLAG_SCROLLABLE);

    uart_dbg_tl = lv_label_create(uart_dbg_term);
    lv_label_set_long_mode(uart_dbg_tl, LV_LABEL_LONG_WRAP);
    lv_label_set_text(uart_dbg_tl, "");
    lv_obj_set_width(uart_dbg_tl, lv_pct(100));
    lv_obj_set_style_text_font(uart_dbg_tl, FONT_BODY, 0);
    lv_obj_set_style_text_color(uart_dbg_tl, lv_color_hex(COL_TEXT), 0);

    /* 打开串口（默认 /dev/uart0 @115200；LD2410B 已让位） */
    dm_uart_dbg_open(DM_UART_DBG_BAUD_DEFAULT);

    /* 200ms 刷新 timer */
    uart_dbg_timer = lv_timer_create(uart_dbg_timer_cb, 200, NULL);
    uart_dbg_timer_cb(NULL);           /* 立即刷一次状态卡 */
}

