替换为 uart_dbg_tool_btn：横向胶囊按钮（lv_btn + icon + label），value 经 user_data 暴露。

按钮风格：lv_btn，高度 DM(26)≈62px，圆角 RAD_CARD，白底 style_card 或半透明，内含 icon label + 主 label（flex row）。value 单独？其实顶部按钮直接一个 label 显示"波特率 115200"或"ASCII"就够了。简化：按钮内部 icon + 文字（label），波特率按钮文字 = "波特率 115200"，显示模式 = "ASCII"，暂停 = "暂停"，清屏 = "清屏"。value label 就是主 label。

那 user_data 存主 label 即可，回调里 lv_label_set_text。

写 tool_btn:
```c
/* 顶部工具栏胶囊按钮（2026-08-27 v3 布局）：横排、圆角、icon+文字；
 * 文字 label 经 user_data 暴露供回调更新（波特率/模式/暂停） */
static lv_obj_t *uart_dbg_tool_btn(lv_obj_t *parent, const char *icon,
                                   uint32_t icon_color, const char *text,
                                   lv_event_cb_t cb)
{
    lv_obj_t *btn = lv_btn_create(parent);
    lv_obj_set_size(btn, LV_SIZE_CONTENT, DM(26));
    lv_obj_set_style_radius(btn, RAD_CARD, 0);
    lv_obj_set_style_bg_color(btn, lv_color_hex(COL_CARD), 0);
    lv_obj_set_style_bg_opa(btn, LV_OPA_70, 0);
    lv_obj_set_style_border_width(btn, 1, 0);
    lv_obj_set_style_border_color(btn, lv_color_hex(0xFFFFFF), 0);
    lv_obj_set_style_border_opa(btn, LV_OPA_50, 0);
    lv_obj_set_style_shadow_width(btn, 4, 0);
    lv_obj_set_style_shadow_opa(btn, LV_OPA_10, 0);
    lv_obj_set_style_pad_hor(btn, DM(14), 0);
    lv_obj_set_flex_flow(btn, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(btn, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(btn, DM(8), 0);
    lv_obj_add_event_cb(btn, cb, LV_EVENT_CLICKED, NULL);

    lv_obj_t *ic = lv_label_create(btn);
    lv_label_set_text(ic, icon);
    lv_obj_set_style_text_font(ic, FONT_ICON, 0);
    lv_obj_set_style_text_color(ic, lv_color_hex(icon_color), 0);

    lv_obj_t *lb = lv_label_create(btn);
    lv_label_set_text(lb, text);
    lv_obj_set_style_text_font(lb, FONT_BODY, 0);
    lv_obj_set_style_text_color(lb, lv_color_hex(COL_TEXT), 0);
    lv_obj_set_user_data(btn, lb);
    return btn;
}
```

