static void uart_dbg_theme_cb(lv_event_t *e)
{
    reset_idle_timer();
    int idx = (int)(intptr_t)lv_obj_get_user_data(lv_event_get_target(e));
    if (idx < 0 || idx >= UART_DBG_THEME_CNT)
        return;
