void ui_uart_dbg_create(lv_obj_t *parent)
{
    /* 2026-08-27 修复：缺 flex column 导致标题/内容全部叠左上角
     * （对照 ui_wifi.c 修复记录）——必须先设 parent 为列布局 */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(parent, DM(6), 0);

    lv_obj_t *big_title = subpage_big_title(parent, "UART 调试");
    lv_obj_set_style_pad_bottom(big_title, 12, 0);

    /* ── 顶部工具栏：状态 + 波特率/显示/暂停/清屏 + 三套配色色块 ── */
    lv_obj_t *bar = make_clean_cont(parent);
    lv_obj_set_size(bar, lv_pct(100), LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(bar, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(bar, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                          LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(bar, DM(12), 0);

    /* 状态文字（已连接/未连接 + 字节数，timer 刷新） */
    uart_dbg_status_lbl = lv_label_create(bar);
    lv_label_set_text(uart_dbg_status_lbl, "未连接");
    lv_obj_set_style_text_font(uart_dbg_status_lbl, FONT_BODY, 0);
    lv_obj_set_style_text_color(uart_dbg_status_lbl, lv_color_hex(COL_BLUE), 0);
    lv_label_set_long_mode(uart_dbg_status_lbl, LV_LABEL_LONG_WRAP);
    lv_obj_set_style_pad_right(uart_dbg_status_lbl, DM(8), 0);

    /* 波特率按钮（点击循环切换） */
    uart_dbg_baud_idx = 0;
    for (int i = 0; i < DM_UART_DBG_BAUD_CNT; i++) {
        if (dm_uart_dbg_bauds[i].baud == DM_UART_DBG_BAUD_DEFAULT) {
            uart_dbg_baud_idx = i;
            break;
        }
    }
    char bbuf[24];
    snprintf(bbuf, sizeof(bbuf), "波特率 %s",
             dm_uart_dbg_bauds[uart_dbg_baud_idx].label);
    lv_obj_t *bd_btn = uart_dbg_tool_btn(bar, LV_SYMBOL_SETTINGS, COL_BLUE,
                                         bbuf, uart_dbg_baud_cb);
    uart_dbg_baud_val = lv_obj_get_user_data(bd_btn);

    /* 显示模式按钮（ASCII/HEX 切换） */
    lv_obj_t *md_btn = uart_dbg_tool_btn(bar, LV_SYMBOL_EDIT, COL_PURPLE,
                                         "显示 ASCII", uart_dbg_mode_cb);
    uart_dbg_mode_val = lv_obj_get_user_data(md_btn);

    /* 暂停/继续按钮 */
    lv_obj_t *pa_btn = uart_dbg_tool_btn(bar, LV_SYMBOL_PAUSE, COL_ORANGE,
                                         "暂停", uart_dbg_pause_cb);
    uart_dbg_pause_val = lv_obj_get_user_data(pa_btn);

    /* 清屏按钮 */
    uart_dbg_tool_btn(bar, LV_SYMBOL_TRASH, COL_RED, "清屏", uart_dbg_clear_cb);

    /* 主题分隔 + 三套配色色块按钮 */
    lv_obj_t *sep = lv_label_create(bar);
    lv_label_set_text(sep, "配色");
    lv_obj_set_style_text_font(sep, FONT_CAPTION, 0);
    lv_obj_set_style_text_color(sep, lv_color_hex(COL_SEC), 0);
    lv_obj_set_style_pad_left(sep, DM(8), 0);

    for (int i = 0; i < UART_DBG_THEME_CNT; i++)
        uart_dbg_theme_btns[i] = uart_dbg_theme_btn(bar, i);

    /* ── 日志窗口：占满剩余（flex_grow=1），配色随主题 ── */
    uart_dbg_term = lv_obj_create(parent);
    lv_obj_set_flex_grow(uart_dbg_term, 1);
    lv_obj_set_width(uart_dbg_term, lv_pct(100));
    lv_obj_set_style_bg_opa(uart_dbg_term, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(uart_dbg_term, RAD_CARD, 0);
    lv_obj_set_style_border_width(uart_dbg_term, 0, 0);
    lv_obj_set_style_shadow_width(uart_dbg_term, 6, 0);
    lv_obj_set_style_shadow_opa(uart_dbg_term, LV_OPA_10, 0);
    lv_obj_set_style_pad_all(uart_dbg_term, DM(14), 0);
    lv_obj_set_scrollbar_mode(uart_dbg_term, LV_SCROLLBAR_MODE_AUTO);
    lv_obj_add_flag(uart_dbg_term, LV_OBJ_FLAG_SCROLLABLE);

    uart_dbg_tl = lv_label_create(uart_dbg_term);
    lv_label_set_long_mode(uart_dbg_tl, LV_LABEL_LONG_WRAP);
    lv_label_set_text(uart_dbg_tl, "");
    lv_obj_set_width(uart_dbg_tl, lv_pct(100));
    lv_obj_set_style_text_font(uart_dbg_tl, FONT_BODY, 0);

    /* 默认配色：深色（One Dark） */
    uart_dbg_theme_idx = 0;
    uart_dbg_apply_theme();

    /* 打开串口（默认 /dev/uart0 @115200；LD2410B 已让位） */
    dm_uart_dbg_open(DM_UART_DBG_BAUD_DEFAULT);

    /* 200ms 刷新 timer */
    uart_dbg_timer = lv_timer_create(uart_dbg_timer_cb, 200, NULL);
    uart_dbg_timer_cb(NULL);           /* 立即刷一次状态 */
}
