/* 把一段原始字节按 ASCII 渲染为文本并追加（v5：显示模式按钮已移除，
 * 固定 ASCII：可打印直出，\r\n 归一为 \n；非打印转 '.'）。 */
static void uart_dbg_feed(const uint8_t *buf, int n)
{
    char tmp[256];
    int  ti = 0;

    for (int i = 0; i < n; i++) {
        uint8_t b = buf[i];
        if (b == '\r')
            continue;               /* 归一化：丢弃 \r，\n 换行 */
        if (ti >= (int)sizeof(tmp) - 2) {
            tmp[ti] = '\0';
            uart_dbg_append(tmp);
            ti = 0;
        }
        if (b == '\n')
            tmp[ti++] = '\n';
        else if (b >= 0x20 && b < 0x7F)
            tmp[ti++] = (char)b;
        else
            tmp[ti++] = '.';
    }
    if (ti > 0) {
        tmp[ti] = '\0';
        uart_dbg_append(tmp);
    }
}

