 * contributor license agreements.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <termios.h>
#include <sys/ioctl.h>

#include "dm_uart_dbg.h"   /* 仅注入接口（同仓头文件） */

#define LOOP_DEV   "/dev/uart1"

/* 自包含内部回环：open → MCR.LOOP → write → read → 关 → close */
static int loop_selftest(void)
{
  static const char msg[] = "UART1-LOOP-TEST-0123456789\r\n";
  char buf[64];
  int fd, mcr, n, total = 0;

  fd = open(LOOP_DEV, O_RDWR | O_NONBLOCK);
  if (fd < 0)
    {
      printf("uartdbg_test: open %s failed errno=%d\n", LOOP_DEV, errno);
      return -1;
    }

  /* 置 MCR.LOOP(bit4)：TX 数据芯片内部环回 RX，不经引脚 */
  mcr = 0x10;
  if (ioctl(fd, TIOCMSET, &mcr) < 0)
    {
      printf("uartdbg_test: TIOCMSET(LOOP) failed errno=%d\n", errno);
      close(fd);
      return -1;
    }

  /* 发测试字节 */
  if (write(fd, msg, sizeof(msg) - 1) < 0)
    {
      printf("uartdbg_test: write failed errno=%d\n", errno);
      close(fd);
      return -1;
    }

  /* 等数据环回 + 驱动接收 */
  usleep(300000);

  /* 读回（非阻塞，尽量读完） */
  for (int i = 0; i < 10; i++)
    {
      n = read(fd, buf, sizeof(buf));
      if (n > 0)
        total += n;
      else
        break;
    }

  /* 关内部回环 */
  mcr = 0;
  (void)ioctl(fd, TIOCMSET, &mcr);
  close(fd);

  return total;
}

int main(int argc, char *argv[])
{
  /* uartdbg_test loop —— 自包含内部回环（不依赖调试工具是否打开） */
  if (argc > 1 && strcmp(argv[1], "loop") == 0)
    {
      int n = loop_selftest();
      if (n > 0)
        {
          printf("uartdbg_test: LOOP OK — controller+driver 全通, rx=%d bytes\n", n);
          return 0;
        }
      printf("uartdbg_test: LOOP FAIL — rx=%d bytes\n", n);
      return -1;
    }

  /* 默认：注入测试日志到 UI 窗口 */
  printf("uartdbg_test: injecting selftest log into UART debug tool...\n");
  if (dm_uart_dbg_inject_test() == 0)
    {
      printf("uartdbg_test: injected OK (see UART debug tool window)\n");
      return 0;
    }

  printf("uartdbg_test: inject FAILED (inject buffer full?)\n");
  return -1;
}

