 * 分别验证各档位下控制器+驱动是否全通——实证子 APP 波特率切换真生效。 */
static int loop_selftest(int baud)
{
  static const char msg[] = "UART1-LOOP-TEST-0123456789\r\n";
  char buf[64];
  int fd, mcr, n, total = 0;

  fd = open(LOOP_DEV, O_RDWR | O_NONBLOCK);
  if (fd < 0)
    {
      printf("uartdbg_test: open %s failed errno=%d\n", LOOP_DEV, errno);
      return -1;
    }

  /* 可选：设置波特率（不传则保持驱动当前值） */
  if (baud > 0)
    {
      struct termios tio;
      if (tcgetattr(fd, &tio) < 0 ||
          cfsetspeed(&tio, (speed_t)baud) < 0 ||
          tcsetattr(fd, TCSANOW, &tio) < 0)
        {
          printf("uartdbg_test: set baud %d failed errno=%d\n", baud, errno);
          close(fd);
          return -1;
        }
    }

  /* 置 MCR.LOOP(bit4)：TX 数据芯片内部环回 RX，不经引脚 */
  mcr = 0x10;
  if (ioctl(fd, TIOCMSET, &mcr) < 0)
    {
      printf("uartdbg_test: TIOCMSET(LOOP) failed errno=%d\n", errno);
      close(fd);
      return -1;
    }

  /* 发测试字节 */
  if (write(fd, msg, sizeof(msg) - 1) < 0)
    {
      printf("uartdbg_test: write failed errno=%d\n", errno);
      close(fd);
      return -1;
    }

  /* 等数据环回 + 驱动接收 */
  usleep(300000);

  /* 读回（非阻塞，尽量读完） */
  for (int i = 0; i < 10; i++)
    {
      n = read(fd, buf, sizeof(buf));
      if (n > 0)
        total += n;
      else
        break;
    }

